MESSAGES = {"en": EN, "zh_sim": ZH_SIM, "zh_tra": ZH_TRA}


class I18n:
    def __init__(self, language: str = "zh_sim") -> None:
        self.language = language if language in MESSAGES else "zh_sim"

    def set_language(self, language: str) -> None:
        self.language = language if language in MESSAGES else "zh_sim"

    def t(self, key: str, **kwargs: object) -> str:
        value = MESSAGES[self.language].get(key, EN.get(key, key))
        try:
            return value.format(**kwargs)
        except (KeyError, ValueError):
            return value
